pub fn list_export_directory() -> std::io::Result<std::process::Output> {
    let directory = std::env::var("EXPORT_DIRECTORY").unwrap_or_else(|_| ".".to_owned());
    std::process::Command::new("powershell")
        .args(["-NoProfile", "-Command"])
        .arg(format!("Get-ChildItem -Path {directory}"))
        .output()
}

pub fn unpack<R: std::io::Read + std::io::Seek>(archive: &mut zip::ZipArchive<R>, destination: &std::path::Path) -> anyhow::Result<()> {
    for index in 0..archive.len() {
        let mut entry = archive.by_index(index)?;
        let output_path = destination.join(entry.name());
        let mut output = std::fs::File::create(output_path)?;
        std::io::copy(&mut entry, &mut output)?;
    }
    Ok(())
}

