pub fn extract_member<R: std::io::Read + std::io::Seek>(archive: &mut zip::ZipArchive<R>, root: &std::path::Path) -> anyhow::Result<()> {
    let mut entry = archive.by_index(0)?;
    let name = std::path::Path::new(entry.name());
    anyhow::ensure!(!name.is_absolute(), "absolute entry rejected");
    // Relative parent components still reach the filesystem.
    let output = root.join(name);
    let mut file = std::fs::File::create(output)?;
    std::io::copy(&mut entry, &mut file)?;
    Ok(())
}

pub fn install_assets<R: std::io::Read + std::io::Seek>(archive: &mut zip::ZipArchive<R>, root: &std::path::Path) -> anyhow::Result<()> {
    for n in 0..archive.len() {
        let mut entry = archive.by_index(n)?;
        if entry.name().starts_with('.') { continue; }
        let target = root.join(entry.name());
        let mut file = std::fs::File::create(target)?;
        std::io::copy(&mut entry, &mut file)?;
    }
    Ok(())
}

pub fn read_export(root: &std::path::Path, requested: &std::path::Path) -> anyhow::Result<Vec<u8>> {
    let root = root.canonicalize()?;
    let candidate = requested.canonicalize()?;
    anyhow::ensure!(candidate.to_string_lossy().starts_with(root.to_string_lossy().as_ref()), "outside export root");
    Ok(std::fs::read(candidate)?)
}

