pub fn inspect_safely(filename: &str) -> std::io::Result<std::process::Output> {
    let quoted = shell_escape::unix::escape(std::borrow::Cow::Borrowed(filename));
    std::process::Command::new("sh").arg("-c").arg(format!("file -- {quoted}")).output()
}

pub fn extract_checked<R: std::io::Read + std::io::Seek>(archive: &mut zip::ZipArchive<R>, root: &std::path::Path) -> anyhow::Result<()> {
    for i in 0..archive.len() {
        let mut entry = archive.by_index(i)?;
        let relative = entry.enclosed_name().ok_or_else(|| anyhow::anyhow!("unsafe ZIP name"))?.to_owned();
        let mut file = std::fs::File::create(root.join(relative))?;
        std::io::copy(&mut entry, &mut file)?;
    }
    Ok(())
}

pub fn extract_relative<R: std::io::Read + std::io::Seek>(archive: &mut zip::ZipArchive<R>, root: &std::path::Path) -> anyhow::Result<()> {
    use std::path::{Component, Path};
    let mut entry = archive.by_index(0)?;
    let relative = Path::new(entry.name());
    anyhow::ensure!(relative.components().all(|c| matches!(c, Component::Normal(_) | Component::CurDir)), "unsafe ZIP path");
    let target = root.join(relative);
    let mut file = std::fs::File::create(target)?;
    std::io::copy(&mut entry, &mut file)?;
    Ok(())
}

pub fn install_package<R: std::io::Read + std::io::Seek>(archive: &mut zip::ZipArchive<R>, root: &std::path::Path) -> zip::result::ZipResult<()> {
    archive.extract(root)
}

pub fn read_confined(root: &std::path::Path, supplied: &std::path::Path) -> anyhow::Result<Vec<u8>> {
    let root = root.canonicalize()?;
    let candidate = supplied.canonicalize()?;
    anyhow::ensure!(candidate.starts_with(&root), "outside root");
    Ok(std::fs::read(candidate)?)
}

pub fn create_document(root: &std::path::Path, relative: &std::path::Path, body: &[u8]) -> anyhow::Result<()> {
    use std::path::Component;
    anyhow::ensure!(relative.components().all(|c| matches!(c, Component::Normal(_))), "relative components required");
    std::fs::write(root.join(relative), body)?;
    Ok(())
}

#[cfg(unix)]
pub fn read_canonical(root: &std::path::Path, supplied: &std::path::Path) -> anyhow::Result<Vec<u8>> {
    let root = root.canonicalize()?;
    let supplied = supplied.canonicalize()?;
    let root_text = root.to_str().ok_or_else(|| anyhow::anyhow!("UTF-8 root required"))?;
    let supplied_text = supplied.to_str().ok_or_else(|| anyhow::anyhow!("UTF-8 path required"))?;
    let boundary = format!("{}/", root_text.trim_end_matches('/'));
    anyhow::ensure!(supplied_text == root_text || supplied_text.starts_with(&boundary), "outside root");
    Ok(std::fs::read(supplied)?)
}

